test('a second search jump clears the previous highlight ring (no stuck rings)', () => {
  vi.useFakeTimers();
  try {
    renderWithKainBain(<ProjectSettings />, {
      projects,
      activeProjectId: 'p1',
      selectProject: vi.fn(),
